const event = $input.first().json;
const message = event?.message;
const text = typeof message?.text === 'string' ? message.text.trim() : '';
const senderId = message?.from?.id;
const chatId = message?.chat?.id;
const messageId = message?.message_id;
const updateId = event?.update_id;

const base = {
  channel: 'telegram',
  externalSenderId: senderId === undefined || senderId === null ? null : String(senderId),
  chatId: chatId === undefined || chatId === null ? null : String(chatId),
  providerMessageId: messageId === undefined || messageId === null ? null : String(messageId),
  message: text,
  locale: typeof message?.from?.language_code === 'string' ? message.from.language_code : 'es-AR',
};

if (!text || !base.externalSenderId || !base.chatId || !base.providerMessageId) {
  return [{ json: { ...base, inputValid: false, dispatch: false, route: 'invalid_transport', safeMessage: 'Solo puedo procesar mensajes de texto válidos.' } }];
}

const deliveryIdentity = [base.channel, base.chatId, base.providerMessageId].join(':');
return [{ json: {
  ...base,
  inputValid: true,
  correlationId: ['tg', updateId ?? 'unknown', messageId].join('-'),
  idempotencyKey: deliveryIdentity,
} }];

// Valores y campos permitidos.
const FORBIDDEN_KEYS = new Set([
  'organizationid', 'tenant', 'residentid', 'channel_user_id', 'channeluserid',
  'unitid', 'buildingid', 'edificioid', 'consorcioid', 'membership', 'permissions',
  'scope', 'ticketid', 'success', 'servicerole', 'service_role', 'apikey', 'api_key',
  'hmacsecret', 'hmac_secret',
]);

const TOP_KEYS = new Set([
  'schemaVersion', 'intent', 'confidence', 'requiresClarification',
  'clarificationReason', 'input',
]);

const INPUT_KEYS = new Set([
  'ticketType', 'priority', 'category', 'description', 'unitNumber',
]);

const TICKET_TYPES = new Set([
  'reclamo', 'urgencia', 'consulta', 'pago',
]);

const PRIORITIES = new Set([
  'alta', 'media', 'baja', 'normal',
]);

const INTENTS = new Set([
  'tickets.create', 'unknown',
]);

// Rechazar propuestas que no cumplan el contrato.
function invalid() {
  return {
    valid: false,
    error: 'model_output_invalid',
  };
}

// Detectar campos prohibidos, incluso dentro de objetos anidados.
function hasForbiddenKey(value) {
  if (!value || typeof value !== 'object') return false;
  if (Array.isArray(value)) return value.some(hasForbiddenKey);

  for (const [key, child] of Object.entries(value)) {
    if (FORBIDDEN_KEYS.has(key.toLowerCase())) return true;
    if (hasForbiddenKey(child)) return true;
  }

  return false;
}

// Validar una propuesta de forma independiente.
function validate(item, index) {
  try {
    const raw =
      item.json?.text ??
      item.json?.output ??
      item.json?.response ??
      item.json?.result ??
      null;

    const proposal = typeof raw === 'string'
      ? JSON.parse(raw.trim())
      : raw;

    if (
      !proposal ||
      typeof proposal !== 'object' ||
      Array.isArray(proposal)
    ) {
      return invalid();
    }

    if (hasForbiddenKey(proposal)) return invalid();

    // Exigir exactamente los campos definidos por el contrato.
    const topKeys = Object.keys(proposal);

    if (
      topKeys.some((key) => !TOP_KEYS.has(key)) ||
      topKeys.length !== TOP_KEYS.size
    ) {
      return invalid();
    }

    if (
      proposal.schemaVersion !== '1' ||
      !INTENTS.has(proposal.intent)
    ) {
      return invalid();
    }

    if (
      typeof proposal.confidence !== 'number' ||
      !Number.isFinite(proposal.confidence) ||
      proposal.confidence < 0 ||
      proposal.confidence > 1
    ) {
      return invalid();
    }

    if (typeof proposal.requiresClarification !== 'boolean') {
      return invalid();
    }

    if (
      proposal.clarificationReason !== null &&
      (
        typeof proposal.clarificationReason !== 'string' ||
        proposal.clarificationReason.trim().length === 0 ||
        proposal.clarificationReason.trim().length > 300
      )
    ) {
      return invalid();
    }

    if (
      proposal.requiresClarification === true &&
      proposal.clarificationReason === null
    ) {
      return invalid();
    }

    // Las solicitudes desconocidas no pueden incluir una acción.
    if (proposal.intent === 'unknown') {
      if (proposal.input !== null) return invalid();

      return {
        valid: true,
        proposal: {
          schemaVersion: '1',
          intent: 'unknown',
          confidence: proposal.confidence,
          requiresClarification: proposal.requiresClarification,
          clarificationReason: proposal.clarificationReason,
          input: null,
        },
      };
    }

    // Una solicitud incompleta debe pedir aclaración sin ejecutar.
    if (proposal.requiresClarification === true) {
      if (proposal.input !== null) return invalid();

      return {
        valid: true,
        proposal: {
          schemaVersion: '1',
          intent: 'tickets.create',
          confidence: proposal.confidence,
          requiresClarification: true,
          clarificationReason: proposal.clarificationReason.trim(),
          input: null,
        },
      };
    }

    if (proposal.clarificationReason !== null) {
      return invalid();
    }

    // Validar los datos necesarios para crear un ticket.
    const input = proposal.input;

    if (
      !input ||
      typeof input !== 'object' ||
      Array.isArray(input)
    ) {
      return invalid();
    }

    const inputKeys = Object.keys(input);

    if (
      inputKeys.some((key) => !INPUT_KEYS.has(key)) ||
      !['ticketType', 'priority', 'category', 'description'].every((key) => inputKeys.includes(key))
    ) {
      return invalid();
    }

    if (
      !TICKET_TYPES.has(input.ticketType) ||
      !PRIORITIES.has(input.priority)
    ) {
      return invalid();
    }

    if (
      typeof input.category !== 'string' ||
      input.category.trim().length === 0 ||
      input.category.trim().length > 100
    ) {
      return invalid();
    }

    if (input.unitNumber !== undefined) {
      const requestedUnit = input.unitNumber;
      const sourceMessage = $('ELI — Entrada común').all()[index]?.json?.message;
      const sourceTokens = typeof sourceMessage === 'string'
        ? (sourceMessage.match(/[\p{L}\p{N}-]+/gu) ?? [])
        : [];
      if (
        typeof requestedUnit !== 'string' ||
        requestedUnit.trim().length === 0 ||
        requestedUnit.trim().length > 32 ||
        !sourceTokens.some((token) => token.toLocaleLowerCase() === requestedUnit.trim().toLocaleLowerCase())
      ) {
        return invalid();
      }
    }

    if (
      typeof input.description !== 'string' ||
      input.description.trim().length === 0 ||
      input.description.trim().length > 2000
    ) {
      return invalid();
    }

    return {
      valid: true,
      proposal: {
        schemaVersion: '1',
        intent: 'tickets.create',
        confidence: proposal.confidence,
        requiresClarification: false,
        clarificationReason: null,
        input: {
          ticketType: input.ticketType,
          priority: input.priority,
          category: input.category.trim(),
          description: input.description.trim(),
          ...(input.unitNumber === undefined ? {} : { unitNumber: input.unitNumber.trim() }),
        },
      },
    };
  } catch {
    return invalid();
  }
}

// Procesar todos los mensajes y conservar su relación de origen.
return $input.all().map((item, index) => ({
  json: validate(item, index),
  pairedItem: {
    item: index,
  },
}));

// Recuperar la propuesta y el mensaje del canal correspondiente.
const verdict = $json;
const transport = $('ELI — Entrada común').item.json;

// Conservar el canal y los datos necesarios para responder.
const base = {
  channel: transport.channel,
  chatId: transport.chatId,
  externalSenderId: transport.externalSenderId,
  providerMessageId: transport.providerMessageId,
  phoneNumberId: transport.phoneNumberId ?? null,
  correlationId: transport.correlationId,
  idempotencyKey: transport.idempotencyKey,
};

// Construir una respuesta sin ejecutar acciones.
function reply(route, safeMessage) {
  return {
    json: {
      ...base,
      dispatch: false,
      route,
      safeMessage,
    },
  };
}

// Rechazar propuestas que no superaron la validación.
if (verdict.valid !== true || !verdict.proposal) {
  return reply(
    'rejected',
    'No pude interpretar el mensaje de forma segura. Intentá nuevamente.'
  );
}

const proposal = verdict.proposal;

// Pedir información cuando la propuesta lo requiera.
if (proposal.requiresClarification === true) {
  return reply('clarification', proposal.clarificationReason);
}

// Responder a saludos y solicitudes fuera del alcance actual.
if (proposal.intent === 'unknown') {
  return reply(
    'conversation',
    'Puedo ayudarte a crear un ticket. Contame qué ocurrió.'
  );
}

// Permitir únicamente la capacidad de crear tickets.
if (proposal.intent !== 'tickets.create' || !proposal.input) {
  return reply(
    'rejected',
    'No pude procesar la solicitud de forma segura.'
  );
}

return {
  json: {
    ...base,
    dispatch: true,
    route: 'tickets.create',
    input: proposal.input,
  },
};

// Recuperar el contexto del mensaje y la solicitud validada.
const value = $json;
const input = value.input;

// Informar a la API el canal real y, solo si fue validado, la unidad
// expresamente mencionada por la persona en su mensaje.
const body = {
  apiVersion: 'v1',
  correlationId: value.correlationId,
  idempotencyKey: value.idempotencyKey,
  capability: 'tickets.create',
  source: {
    channel: value.channel,
    externalSenderId: value.externalSenderId,
    ...(typeof input?.unitNumber === 'string' && input?.unitNumber.trim()
      ? { unitNumber: input.unitNumber.trim() }
      : {}),
  },
  input: {
    ticketType: input.ticketType,
    priority: input.priority,
    category: input.category,
    description: input.description,
  },
};

// Serializar el cuerpo que luego firmará la cadena SEC-01.
return {
  json: {
    ...value,
    rawBody: JSON.stringify(body),
    requestPath: '/api/integrations/n8n/v1/tickets.create',
  },
};

// Leer la firma recibida y el HMAC calculado.
const item = $input.first();
const received = item.json.headers?.['x-hub-signature-256'];
const expected = item.json.metaExpectedSignature;

// Comprobar el formato antes de comparar.
const receivedValid =
  typeof received === 'string' &&
  /^sha256=[a-f0-9]{64}$/i.test(received);

const expectedValid =
  typeof expected === 'string' &&
  /^[a-f0-9]{64}$/i.test(expected);

// Comparar todos los caracteres sin salir en la primera diferencia.
let signatureValid = false;

if (receivedValid && expectedValid) {
  const actual = received.slice(7).toLowerCase();
  const calculated = expected.toLowerCase();
  let difference = 0;

  for (let index = 0; index < 64; index++) {
    difference |= actual.charCodeAt(index) ^ calculated.charCodeAt(index);
  }

  signatureValid = difference === 0;
}

// Conservar los datos para el procesamiento posterior.
return [{
  ...item,
  json: {
    ...item.json,
    signatureValid,
    responseCode: signatureValid ? 200 : 403,
    responseBody: signatureValid ? 'EVENT_RECEIVED' : 'Forbidden',
  },
}];

// Configuración: número de WhatsApp de ELI en Meta.
const phoneNumberId = 'REVIEW_PHONE_NUMBER_ID';
const output = [];

// Recorrer los eventos que superaron la validación de firma.
for (const [itemIndex, item] of $input.all().entries()) {
  if (item.json.signatureValid !== true) continue;

  const body = item.json.body;

  if (body?.object !== 'whatsapp_business_account') continue;

  // Un evento puede contener varias entradas y mensajes.
  for (const entry of body.entry ?? []) {
    for (const change of entry.changes ?? []) {
      const value = change.value;

      if (change.field !== 'messages') continue;
      if (value?.metadata?.phone_number_id !== phoneNumberId) continue;

      // Ignorar estados de entrega y procesar solo mensajes de texto.
      for (const incoming of value.messages ?? []) {
        if (incoming.type !== 'text') continue;

        const text = incoming.text?.body?.trim();
        const senderId = incoming.from;
        const messageId = incoming.id;

        if (!text || !senderId || !messageId) continue;

        // Entregar los mismos campos base que la entrada de Telegram.
        output.push({
          json: {
            channel: 'whatsapp',
            externalSenderId: String(senderId),
            chatId: String(senderId),
            providerMessageId: String(messageId),
            phoneNumberId,
            message: text,
            locale: 'es-AR',
            inputValid: true,
            correlationId: `wa-${messageId}`,
            idempotencyKey: [
              'whatsapp',
              phoneNumberId,
              messageId,
            ].join(':'),
          },
          pairedItem: {
            item: itemIndex,
          },
        });
      }
    }
  }
}

return output;

// Conservar cada mensaje y vincularlo con su entrada correspondiente.
return $input.all().map((item, index) => ({
  json: { ...item.json },
  pairedItem: {
    item: index,
  },
}));

const value = $json;
const isLocalReply = Boolean(value.route && value.route !== 'tickets.create');
const context = isLocalReply ? value : $('Capability Router').item.json;
if (!['telegram', 'whatsapp'].includes(context.channel) || !context.chatId) {
  throw new Error('fail_closed_missing_response_context');
}
function reply(responseText, outcome, extra = {}) {
  return { json: {
    channel: context.channel,
    chatId: context.chatId,
    phoneNumberId: context.phoneNumberId ?? null,
    correlationId: context.correlationId,
    responseText,
    outcome,
    ...extra,
  }};
}
if (isLocalReply) {
  const text = typeof value.safeMessage === 'string' ? value.safeMessage.trim().slice(0, 300) : '';
  return reply(text || 'No pude procesar la solicitud de forma segura.', value.route);
}
let response = value.body ?? value.data ?? value;
if (typeof response === 'string') {
  try { response = JSON.parse(response); } catch { response = null; }
}
const ticketCode = typeof response?.result?.ticketCode === 'string' ? response.result.ticketCode.trim() : '';
const ticketId = typeof response?.result?.ticketId === 'string' ? response.result.ticketId.trim() : '';
const status = Number(value.statusCode);
const authoritative = status >= 200 && status < 300 &&
  response?.apiVersion === 'v1' && response?.capability === 'tickets.create' &&
  response?.correlationId === context.correlationId;
if (authoritative && response?.outcome === 'success' && ticketCode && ticketId) {
  return reply(`✅ Tu reclamo fue registrado.
Número de ticket: ${ticketCode}`, 'success', { ticketId, ticketCode });
}
const messages = {
  clarification_required: 'Necesito más información para crear el ticket.',
  idempotency_conflict: 'El mensaje ya fue procesado con datos diferentes. No se creó otro ticket.',
  identity_unresolved: 'No pude verificar tu identidad para crear el ticket.',
  identity_blocked: 'No puedo crear el ticket para esta identidad.',
  identity_inactive: 'No puedo crear el ticket para esta identidad.',
  cross_tenant: 'No puedo procesar esta solicitud.',
  capability_denied: 'No estás autorizado para crear este ticket.',
  authentication_failed: 'No pude autenticar la solicitud.',
  replay: 'La solicitud ya fue procesada. No pude confirmar el resultado del ticket.',
  invalid_request: 'La solicitud no es válida.',
  internal_error: 'No pude verificar la creación del ticket. No voy a repetirla automáticamente.',
};
const outcome = response?.outcome === 'success' ? 'invalid_authoritative_response' : response?.outcome ?? 'transport_error';
return reply(messages[outcome] || 'No pude confirmar la creación del ticket.', outcome);
